/**
 * Bespoke AI-Overview answers, one per tool, a concise, answer-first,
 * entity-rich ~40-55 word summary rendered in the tool page AI-answer callout
 * and speakable schema. Each is grounded in that tool's real config/engine.
 *
 * Server-only data: imported by app/[tool]/page.tsx at build time. It is NOT
 * pulled into any client bundle. Keyed by tool slug.
 */

export const TOOL_ANSWERS: Record<string, string> = {
  "aac-converter": "The AAC Converter encodes audio into AAC (Advanced Audio Coding), the MP3 successor that sounds cleaner at the same bitrate and plays natively on iPhone, Android, YouTube and video apps. It decodes WAV, MP3, M4A, OGG or FLAC with the Web Audio API, previews the waveform, then writes a compact .aac file locally in your browser. Nothing is uploaded.",
  "app-download-qr-code-generator": "The App Download QR Code Generator encodes your App Store, Google Play or smart-link URL into one scannable install QR for posters, packaging and slides. Brand it with colors and your app icon, verify it scans, and export print-ready PNG, SVG, PDF or EPS. Free and fully in-browser, honest that one code holds a single URL.",
  "app-store-qr-code-generator": "The App Store QR Code Generator converts any apps.apple.com link into a scannable code that opens your iOS listing on iPhone and iPad, ready for a one-tap Get. Style it, add your app icon or logo, verify it scans, then export PNG, SVG, PDF or EPS. Free, no signup or watermark, and runs entirely in your browser.",
  "article-schema-generator": "The Article Schema Generator builds valid Article, BlogPosting and NewsArticle JSON-LD, nesting author and publisher graphs with published/modified dates, hero images and keywords. A live SERP preview and required/recommended validity check confirm rich-result eligibility. It's free and runs in your browser, so draft headlines never leave your device.",
  "audio-compressor": "The Audio Compressor shrinks audio file size by lowering the MP3 bitrate (96–320 kbps) and sample rate, the two settings that truly control weight. Drop a WAV, MP3, M4A, OGG or FLAC and it re-encodes to CBR MP3 with lamejs, showing the exact before/after byte count. Free, entirely in-browser, with nothing uploaded to any server.",
  "audio-cutter": "The Audio Cutter removes a section from the middle of a recording and closes the gap. Drop an MP3, WAV, M4A or OGG, drag a region over the part to delete on the real waveform, and the audio before and after joins into one seamless clip. Export a lossless WAV or compact MP3, sample-accurate and processed privately in the browser.",
  "audio-fade": "Audio Fade In / Out adds smooth volume ramps to the start and end of a track. Drop an MP3, WAV, M4A or OGG, set fade lengths by dragging handles or typing seconds, and pick the shape: Smooth (an equal-power curve that holds steady perceived loudness, the default), Linear, or Gentle for a long music tail. A translucent overlay shows the ramp on a live waveform. Preview, then download a lossless WAV or compact MP3. Sample-accurate and fully private in the browser.",
  "audio-format-converter": "The Audio Format Converter switches audio between MP3, WAV, OGG, FLAC, M4A and AAC in any direction. Drop a file, choose a target and matching quality controls (bitrate for lossy, full samples for lossless), preview the waveform, then download. WAV and MP3 use native code. Exotic targets load an on-demand codec. Everything runs locally, nothing uploaded.",
  "audio-joiner": "The Audio Joiner concatenates several clips into one continuous track. Drop multiple MP3, WAV, M4A or OGG files, drag to reorder them, and they stitch end-to-end on exact sample boundaries with no gaps or drift. Preview the whole sequence, then download one seamless WAV or MP3. Each clip decodes on your device, so nothing is uploaded.",
  "audio-merger": "The Audio Merger combines multiple recordings into a single file. Drop MP3, WAV, M4A or OGG clips, drag rows to set the running order, and choose a clean gapless join or a crossfade that overlaps each clip smoothly. A live total shows the finished length. Download one lossless WAV or compact MP3: merged entirely in the browser, nothing uploaded.",
  "audio-metadata": "The Audio Metadata Viewer inspects an audio file and reports its exact decoded duration, sample rate in kHz, channel layout (mono/stereo), file size, MIME type, detected format and estimated bitrate. Because length is measured from decoded samples, even variable-bitrate or mislabelled files show the truth. Reading happens on-device with the Web Audio engine. Nothing is uploaded.",
  "audio-normalizer": "The Audio Normalizer lifts a too-quiet recording to a clean target level using peak or RMS normalisation to an exact dBFS ceiling like −1 or −3. Drop a voice memo, interview or song, compare the before/after waveform, then download WAV or MP3. It decodes and re-levels every sample on the native Web Audio engine, so nothing leaves your device.",
  "audio-player": "The Audio Player is a private, browser-based player for MP3, WAV, M4A and OGG files that paints a real waveform on drop. Click the wave to seek, change playback speed, loop the track, or set an A–B repeat to drill one passage. Audio is decoded locally and played untouched: nothing is uploaded, re-encoded or exported.",
  "audio-recorder": "The Audio Recorder captures your microphone directly in the browser using getUserMedia and MediaRecorder, showing a live level meter and timer. Pause and resume takes, trim dead air off the ends on a waveform, then export a clean WAV or MP3. No plugin or account is needed, and your audio never leaves your device.",
  "audio-reverse": "Audio Reverse plays a track backwards by walking its samples from the last frame to the first, a true, sample-accurate reversal, not a playback trick. Drop an MP3, WAV, M4A or OGG, view its waveform, preview the reversed result, then download a bit-perfect lossless WAV. Reverse twice and you recover the original. Runs entirely in-browser. Nothing is uploaded.",
  "audio-silence-remover": "The Audio Silence Remover strips silent gaps and dead air from a recording. Drop an MP3, WAV, M4A or OGG, set a dBFS threshold, a minimum-gap length and how much breathing room to keep around speech, and the kept segments light up on a real waveform while a readout shows time reclaimed. Loudness is measured as windowed RMS like a real level meter, and every cut is crossfaded so the joins don't click. Preview the tighter cut, then download a lossless WAV or MP3: all processed privately in the browser.",
  "audio-speed-changer": "The Audio Speed Changer speeds up or slows down a track from 0.5× to 2× with a single slider and preset ratios. Pitch is preserved by default using real WSOLA time-stretching, so a podcast at 1.5× is the same voice talking faster rather than a chipmunk, or switch it off for the classic tape effect where pitch follows speed. Drop an MP3, WAV, M4A or OGG, watch a live readout of the exact new duration on a real waveform, preview, then download a lossless WAV or compact MP3. Fully private and in-browser. Nothing is uploaded.",
  "audio-splitter": "The Audio Splitter breaks one file into multiple clips, by fixed-length chunks, by your own start/end time ranges, or automatically on silence. Drop an MP3, WAV, M4A, OGG or FLAC, preview each part on its waveform, then download them individually or as a single ZIP. Sample-accurate, lossless WAV output, and 100% private in the browser.",
  "audio-to-mp3": "GigAI Audio to MP3 converts WAV, M4A, OGG and FLAC to MP3 in your browser using the lamejs encoder - decode with the Web Audio API, re-encode locally, download. No upload, no account, no length cap. Lossless-to-lossy honesty: pick a higher bitrate if the source matters.",
  "audio-trimmer": "The Audio Trimmer keeps exactly the part of a clip you want. Drop an MP3, WAV, M4A or OGG, drag a selection region on the real waveform, slide it or nudge edges with arrow keys for frame-level precision, then preview. Download a lossless WAV or compact MP3. Sample-accurate and fully private: the file is decoded locally and never uploaded.",
  "audio-volume-booster": "GigAI Audio Volume Booster raises (or lowers) a recording's loudness in your browser with true gain processing and a clipping-aware preview - not a fake slider. Decode, adjust, re-encode to MP3 or lossless WAV locally. The recording never leaves your device.",
  "audio-waveform": "GigAI Audio Waveform draws an accurate waveform of any audio file in your browser and exports it as an image - useful for podcasts, social clips and edit planning. Decoding uses the Web Audio API on your device. The audio is never uploaded.",
  "avi-to-mp4": "The AVI to MP4 converter re-encodes legacy AVI files (DivX, Xvid or MJPEG video with MP3 or PCM audio) into universal H.264/AAC MP4 using FFmpeg in your browser. A genuine transcode with yuv420p pixels and web-ready faststart, plus an in-page preview and download. Free, and nothing is uploaded.",
  "barcode-generator": "GigAI Barcode Generator produces Code 128, EAN-13, UPC and more as crisp SVG or PNG in your browser - checksums computed correctly, quiet zones respected, print-ready at any size. Free with no account, and the values you encode never leave your device.",
  "base64-decoder": "Decoding Base64 back to its original form, the Base64 Decoder recovers UTF-8 text without mojibake and auto-detects both standard and URL-safe input, including JWT segments and data URLs. When the payload is a PNG, PDF, ZIP or similar binary, it sniffs the type and offers a download. Free and fully in-browser. Nothing is uploaded.",
  "base64-encoder": "The Base64 Encoder converts text or any file to Base64 the moment you enter it, encoding through UTF-8 so emoji and accents round-trip cleanly. Drop in an image, PDF or font to get a ready-to-embed data URL, and flip the URL-safe toggle for JWTs and query strings. Free, and everything stays in your browser.",
  "breadcrumb-schema-generator": "The Breadcrumb Schema Generator turns an ordered trail of pages into valid BreadcrumbList JSON-LD, auto-numbering each ListItem position and previewing the trail as Google shows it (example.com › Blog › SEO). It checks every crumb has a name and URL, then outputs a copy-ready script tag entirely in your browser.",
  "bulk-qr-code-generator": "Upload a CSV and the Bulk QR Code Generator turns every row into its own QR code, from URLs and Wi-Fi to vCards across 28 payload types. Apply one shared style with colors, logo and dot shapes, name each file from a column, and download all codes as PNG or SVG in a ZIP. Runs entirely in-browser with nothing uploaded.",
  "business-card-qr-code-generator": "The Business Card QR Code Generator packs your name, title, company, phones, email, website and address into a vCard 3.0 QR that phone cameras save straight to Contacts. Add a logo, brand the colors, and download print-ready PNG, SVG or PDF for cards and badges. Everything is built in your browser with no upload.",
  "calendar-qr-code-generator": "Enter an event title, date, time and place and the Calendar QR Code Generator encodes them into a scan-to-add code offering a one-tap 'Add to calendar' with fields pre-filled. Set start and end times or flag all-day, brand it with your colors and logo, then download print-ready PNG, SVG or PDF. Free and fully in your browser.",
  "campaign-url-builder": "The Campaign URL Builder generates correctly-encoded UTM and tracking links, adding utm_source, utm_medium, utm_campaign, utm_term, utm_content plus unlimited custom parameters. Channel presets for Google Ads, Meta, LinkedIn and email keep reports consistent, while a live parameter table and lint checks catch mistakes. Free and browser-based, nothing is uploaded.",
  "canonical-url-generator": "The Canonical URL Generator normalises any page URL, fixing scheme and host casing, tidying the path and stripping UTM and tracking parameters, then outputs a rel=canonical link tag, HTTP Link header and Next.js, WordPress and plain-HTML snippets. A before/after diff shows what changed. Free, runs locally, no URLs uploaded.",
  "character-counter": "The Character Counter tallies characters with and without spaces, plus words, sentences, lines, paragraphs and true UTF-8 bytes as you type. Live meters check text against SEO title (50–60), meta description (150–160), X/Twitter (280) and SMS (160) limits. Free and browser-based, so drafts stay on your device.",
  "compress-pdf": "GigAI Compress PDF re-renders each page and re-encodes it with MozJPEG, entirely in your browser - the document is never uploaded. In our published benchmark a 6.6 MB image-heavy PDF became 90 KB (99% smaller) in 2.2 seconds. If compression can't beat your original, you get the original back. Free, no account, no daily limit.",
  "cron-generator": "The Cron Expression Generator builds and decodes crontab schedules visually. Pick presets or per-field rules, read a plain-English description, and preview the next five run times. Paste an existing expression to reverse-parse it back into fields. Free and fully client-side, it runs entirely in the browser with nothing uploaded.",
  "crop-image": "GigAI Crop Image cuts an exact region from a JPG, PNG or WebP with a 1:1 source-pixel copy - the kept area is never rescaled or re-encoded beyond the crop itself, so quality is untouched. Aspect presets cover profile pictures and covers. Runs in your browser: no upload, no account, no watermark.",
  "csp-generator": "The CSP Generator builds a Content-Security-Policy header from a per-directive form, setting trusted sources for script-src, style-src, img-src, connect-src, font-src and frame-ancestors with correct quoting. A live strictness meter scores XSS protection and explains each directive. Free and fully local, so internal hostnames and CDN URLs never leave the tab.",
  "css-beautifier": "The CSS Beautifier formats and prettifies CSS, SCSS and LESS using the Prettier engine, auto-detecting the flavour and reflowing declarations, spacing, quoting and nested rules. Control indent width and print width, and get precise error line and column on malformed sheets. Free and browser-based, so your stylesheets never leave the tab.",
  "css-minifier": "Compressing stylesheets with the csso engine, the CSS Minifier does structural optimisation (not just whitespace stripping) and reports exact bytes and percentage saved. Toggle restructuring off for a conservative, auditable pass, and minify live as you type, paste or import. Free and fully in-browser, your CSS stays on your device.",
  "css-validator": "The CSS Validator is a structural linter that walks pasted stylesheets to catch unbalanced braces, unclosed and empty rules, and unterminated comments or strings, pinpointing each to a line. It's a balance checker rather than a full W3C validator. Free and browser-based, so unreleased design tokens and client themes stay private.",
  "csv-editor": "The CSV Editor opens comma-, tab- or semicolon-delimited files as a real, editable spreadsheet grid in your browser. Fix individual cells, add or delete rows and columns, sort, search across everything, then export back to CSV, JSON or a genuine Excel .xlsx. Quoting-aware parsing handles big files. Nothing is uploaded.",
  "csv-to-excel": "CSV to Excel converts a pasted or dropped .csv into a real Excel .xlsx workbook, not a renamed file. The delimiter is auto-detected, the parsed grid previews live, and you can name the worksheet before downloading a workbook that opens natively in Excel, Google Sheets and LibreOffice. Free and fully in-browser.",
  "csv-to-json": "CSV to JSON turns a pasted or dropped .csv into a clean JSON array of objects or arrays, with a header toggle, optional number and boolean type inference, and pretty or minified output. The delimiter is sniffed automatically and live row, column and size badges update as you go. Free, client-side, nothing uploaded.",
  "csv-viewer": "The CSV Viewer opens CSV files as a fast, read-only spreadsheet in your browser. Sort any column, search across every cell, and read a live per-column profile showing type, fill rate and min/max/mean. Quoting-aware parsing handles big files, and because it never edits, your data stays untouched and private.",
  "data-uri-to-svg": "The Data URI to SVG decoder converts a data:image/svg+xml URI back into clean, editable SVG markup. It auto-detects base64 or URL-encoded payloads pulled from CSS, an img src or a minified bundle, shows a live preview, and downloads a .svg file. Free and fully in-browser, nothing is uploaded.",
  "delete-pdf-pages": "Delete PDF Pages removes unwanted pages from a single PDF by ticking them on a thumbnail grid, then rebuilds a fresh document from only the pages you keep using pdf-lib. Kept pages stay unchanged, a guard blocks emptying the file, and everything runs privately in your browser with no upload and no watermark.",
  "diff-checker": "The Diff Checker compares two versions of text or code and highlights every insertion and deletion in color. Switch between line, word and character granularity, unified or side-by-side views, and ignore whitespace or case to hide noise. Free and entirely client-side: your text is never uploaded, logged or seen by anyone.",
  "discord-qr-code-generator": "The Discord QR Code Generator turns any invite link, whether discord.gg/abc123 or a custom vanity URL, into a scannable code that opens the Discord invite screen so people join by pointing their camera. Brand it with server colors, rounded dots and your logo, then download print-ready PNG, SVG or PDF. Runs entirely in your browser.",
  "document-comparer": "The Document Comparer shows exactly what changed between two files. Upload any two PDF, Word, RTF, text or Markdown documents and get a color-coded redline, additions in green and removals in red, at line or word granularity with a live added/removed count. Runs entirely in your browser. Nothing is uploaded.",
  "document-metadata-editor": "The PDF Metadata Editor reveals and edits a PDF's document properties, including title, author, subject, keywords, creator, producer and dates, then downloads the updated file. One click strips all metadata for privacy, edits are lossless with pages untouched, and you can copy the properties as JSON. Free and fully in-browser.",
  "document-organizer": "The Document Organizer lets you reorder, rotate and delete PDF pages on one visual canvas. Every page renders as a thumbnail you can drag to rearrange, rotate in lossless 90-degree steps, and mark for removal, then rebuild and download a tight, clean PDF. Everything happens in your browser. Nothing is uploaded.",
  "document-page-number": "Add Page Numbers to PDF stamps numbers onto a PDF in your browser. Choose one of six corner positions, a bare number or a 'Page X of Y' label, set the start number, font size and margin, and skip a cover page. The numbers are real selectable text, and nothing is uploaded.",
  "document-signature": "Sign PDF lets you add a signature to a PDF for free in your browser. Draw your signature, type your name in a handwritten font, or upload a signature image, then drag it onto the correct page, resize it to fit and download a signed PDF. No printing or scanning. Nothing is uploaded.",
  "document-viewer": "The Document Viewer opens almost any document in your browser. Drop a PDF, CSV, Excel, text, Markdown, EPUB, RTF or image file and it auto-detects the format, showing paged PDFs, scrollable spreadsheets, rendered Markdown and more. Previews are lazy-loaded and you can download the original. Fully private. Nothing is uploaded.",
  "document-watermark": "Watermark PDF stamps a text or image watermark across every page of a PDF. Set the opacity, angle and size, tile it or centre it, and preview the result before exporting, using labels like DRAFT or CONFIDENTIAL, or a logo image. Free and fully in your browser. Nothing is uploaded.",
  "dynamic-qr-code-generator": "The Dynamic QR Code Generator builds a printed code that stays fixed while its destination stays editable, without vendor lock-in. Encode a short redirect link you own, on your domain or shortener, so you can re-point it later without reprinting. Brand and verify it, then export PNG, SVG or PDF. Free and fully in-browser.",
  "email-qr-code-generator": "The Email QR Code Generator builds a mailto: QR that opens a pre-filled email with the recipient, subject and message ready to send in the phone's native mail app. Enter the address and optional subject and body, style the code, add a logo, then download print-ready PNG, SVG or PDF. Encoded entirely in your browser.",
  "eps-to-png": "EPS to PNG converts Adobe Illustrator EPS and AI files into high-resolution PNG in your browser. It reads the PDF payload Illustrator embeds when \u201cCreate PDF Compatible File\u201d is on and renders it with pdf.js at up to 4\u00d7, preserving transparency. Files holding only raw PostScript are refused honestly, with the one-step fix.",
  "epub-to-pdf": "EPUB to PDF converts a DRM-free .epub ebook into a clean, printable PDF in your browser. Chapters are read in reading order and paginated to A4 or US Letter, with text, headings and images intact. Free and fully client-side, it's also honest about reflow limits. Nothing is uploaded.",
  "epub-viewer": "The EPUB Viewer opens and reads any .epub book in your browser as a paginated, book-like reader. It includes a table-of-contents sidebar, adjustable font size and light, sepia or dark themes. Everything runs on your device, so the book is never uploaded and never leaves your machine. Free to use.",
  "event-qr-code-generator": "The Event QR Code Generator encodes a title, place and start and end times into a scannable code that adds the event to Apple or Google Calendar in one tap. Flag all-day events, add a description, brand it with colors and a logo, then export print-ready PNG, SVG or PDF. Free and built entirely in your browser.",
  "event-schema-generator": "The Event Schema Generator produces valid Event JSON-LD for concerts, conferences and webinars, capturing dates, venue or virtual location, organizer, performer and ticket offers with price and availability. It expands status and attendance-mode shorthands and validates against Google's required fields. Free and browser-based, so unannounced dates never leave your machine.",
  "excel-to-csv": "Excel to CSV converts an .xlsx or .xls workbook into a clean CSV in your browser. Drop the file, pick the sheet you want from multi-sheet workbooks, and download a correctly-quoted, RFC-4180 CSV that handles commas inside cells and quoted fields. Free and fully client-side. Nothing is uploaded.",
  "excel-to-pdf": "Excel to PDF converts an .xlsx, .xls or .ods spreadsheet into a clean, printable PDF in your browser. Pick the sheet from a live preview, choose portrait or landscape and A4 or US Letter, then download a bordered table PDF. Free, fast and private, with nothing uploaded.",
  "extract-audio": "Extract Audio from Video rips the sound track out of an MP4, MOV, WEBM, MKV, AVI or M4V file and saves it as MP3, WAV, AAC, M4A or OGG. Built on FFmpeg in the browser, it shows a live progress bar and lets you preview before download. Free and fully private.",
  "extract-pdf-pages": "Extract PDF Pages lets you hand-pick any pages from a PDF, clicking them on a live thumbnail grid, and copies just those into a brand-new file with pdf-lib. Pages keep their original order and quality, text stays selectable, and the whole process runs free in your browser with no uploads or watermark.",
  "facebook-qr-code-generator": "The Facebook QR Code Generator turns any Facebook profile, Page, Group, event or post link into a branded, scannable code so people follow you by pointing their camera. It validates the URL, adds https:// if missing, then lets you style colors and drop in a logo. Download print-ready PNG, SVG or PDF, all in-browser with nothing uploaded.",
  "faq-schema-generator": "The FAQ Schema Generator converts a list of questions and answers into valid FAQPage JSON-LD, reordering entries and preserving HTML in answers. A validity check confirms each Question has a name and Answer text, then outputs a copy-ready script tag. Free and browser-based, so support content stays on your device.",
  "flac-converter": "The FLAC Converter encodes audio to FLAC, the Free Lossless Audio Codec that preserves every sample bit-for-bit yet runs roughly 40–60% smaller than uncompressed WAV. Drop WAV, MP3, M4A, AAC or OGG and an on-device ffmpeg engine writes a standard, universally-readable .flac with a waveform preview and exact size readout. Ideal for archiving. Nothing is uploaded.",
  "gif-to-video": "GIF to Video converts a heavy animated GIF into a smaller, smoother MP4 (H.264) or WebM (VP9). Because modern codecs compress across frames while GIF barely does, the same animation typically shrinks to a fraction of its size. Faststart, preview and download, free, all in the browser with nothing uploaded.",
  "gigai-verify":
    "GigAI Verify examines a file's evidence - metadata, Content Credentials, structure and compression - in your browser, and reports what that evidence supports with its alternative explanations. It never issues a fake certainty verdict, because honest analysis can't. Images, PDFs, audio, video and pasted text. Nothing is uploaded.",
  "google-maps-qr-code-generator": "The Google Maps QR Code Generator turns an address, place name or Maps link into a code that opens your pin in Google Maps with one-tap directions on iPhone and Android. Paste a place page, plus code or lat/long, brand it with colors and a logo, then download print-ready PNG, SVG or PDF. Runs entirely in your browser.",
  "google-play-qr-code-generator": "The Google Play QR Code Generator turns your play.google.com listing URL into a scannable code that sends Android users straight to your install button, landing on the correct package rather than a search result. Brand it with colors and a logo, verify it scans, then download print-ready PNG, SVG or PDF. Free and fully in your browser.",
  "google-serp-preview": "Google SERP Preview renders a pixel-accurate desktop and mobile search snippet as you type your title, URL and meta description, measuring text by rendered pixel width like Google to warn where truncation occurs. A paste-first mode extracts tags from any page's HTML. Free and browser-based, so unpublished pages stay private.",
  "hash-generator": "Computing MD5, SHA-1, SHA-256, SHA-384 and SHA-512 checksums of any text or file at once, the Hash Generator also signs messages with keyed HMAC and verifies a download against its expected hash. It runs on the browser's native Web Crypto API, so inputs, keys and files are never uploaded or logged. Free to use.",
  "heading-checker": "The Heading Checker parses pasted HTML to draw its H1–H6 outline as an indented tree, flagging a missing H1, multiple H1s, skipped levels and empty headings with a plain-English fix for each. A structure score and per-level counts summarise the page. Free and local, so staging drafts stay private.",
  "heic-to-jpg":
    "GigAI HEIC to JPG converts iPhone photos to universally-supported JPG in your browser - the photos are never uploaded, and after your first visit it works offline. Our benchmark converted a 2.3 MB HEIC in 5.7 seconds. Honest note: JPG is usually larger than HEIC at equal quality. Convert for compatibility, then compress if size matters.",
  "html-formatter": "The HTML Formatter beautifies or minifies markup, reindenting tangled HTML, wrapping long lines and fixing nesting readability, or collapsing to production-ready output. It handles full documents and loose fragments, with tunable indent and print width. Free and client-side, so your markup is processed in the browser and never uploaded.",
  "html-minifier": "The HTML Minifier shrinks page weight by collapsing whitespace and stripping comments, while safely preserving the contents of pre, textarea, script and style tags. A live readout shows exactly how many bytes you saved. It is free and runs entirely in the browser, so your markup never leaves the tab.",
  "html-sitemap-generator": "The HTML Sitemap Generator turns a pasted list of URLs into a nested, linkable sitemap page, grouping links by folder path so /blog/2026/post nests under /blog. Export the semantic UL fragment or a complete styled sitemap.html to boost navigation and internal linking. Free and browser-based, with no crawl and nothing uploaded.",
  "html-to-pdf": "HTML to PDF turns pasted HTML or a dropped .html file into a clean, print-ready PDF. A live sandboxed preview renders your markup exactly as-is with inline CSS honoured, then one click paginates it to A4 or US Letter with tunable margins. Runs in your browser. No external assets are fetched and nothing is uploaded.",
  "html-validator": "The HTML Validator parses pasted markup to check well-formedness and on-page SEO at once, flagging unclosed tags, a missing single title, meta description and lang attribute, image alt coverage, empty links and the full heading outline. Each warning ships with a fix. Free and local, so confidential markup stays private.",
  "http-header-checker": "The HTTP Header Checker parses raw response headers from curl or DevTools into a clean table, then interprets the status line, redirect chain, caching, gzip/Brotli compression, Set-Cookie flags and CORS. It also grades HSTS, CSP and other security headers 0–100. Free and browser-based, so headers from staging boxes stay private.",
  "gigai-fit":
    "GigAI Fit takes any file and a size limit - \u201cget this under 10 MB\u201d - identifies what the file actually is from its bytes, and searches for the best quality that fits, entirely in your browser. Built for upload caps: Gmail's 25 MB, Discord's 10 MB, portal and form limits. Nothing is uploaded, no account, no watermark.",
  "icon-lab":
    "GigAI IconLab builds a consistent icon system from one set of design decisions: define the family's stroke, corner and grid language once, and every icon you add matches it. Export SVG, PNG, React, Vue and a sprite in one package. A 98-concept vocabulary. Runs in your browser with nothing uploaded.",
  "image-compressor": "GigAI Image Compressor reduces JPG, PNG and WebP file sizes in your browser using the MozJPEG and libwebp encoders. In our published benchmark, a 3.4 MB 4000\u00d73000 photograph became 515 KB - 85% smaller - in 2.7 seconds, with no visible difference at full zoom. No upload, no account, no watermark, no file-size limit.",
  "image-qr-code-generator": "The Image QR Code Generator encodes the direct URL of a hosted photo, from your CDN, S3, Cloudinary, Imgur or Drive, into a QR that opens the picture full-screen in a phone's browser. Brand it with colors and a logo, verify it scans, then export PNG, SVG, PDF or EPS. Built in-browser with nothing uploaded.",
  "image-resizer": "GigAI Image Resizer scales JPG, PNG and WebP to exact pixel dimensions with Lanczos resampling (via pica), in your browser. Our benchmark took a 4000\u00d73000 photo to 1600\u00d71200 in 3.1 seconds, 3.4 MB down to 292 KB. Aspect-ratio lock, platform presets, no upload, no watermark, no account.",
  "image-sitemap-generator": "The Image Sitemap Generator pairs each page URL with its hosted images and emits a valid Google image sitemap using image:image, image:title and image:caption, escaping XML-unsafe characters. Live validation flags non-HTTPS or duplicate image URLs and the 1,000-per-page and 50,000-URL limits. Free and browser-based, so CDN-hosted assets never leave your machine.",
  "image-upscaler": "The AI Image Upscaler enlarges photos and graphics 2x or 4x using a real ESRGAN super-resolution model powered by UpscalerJS and TensorFlow.js. Rather than stretching pixels, it reconstructs sharp edges and texture. Model weights download once and cache. Inference runs in your browser, so nothing is uploaded. Free, transparency preserved.",
  "instagram-qr-code-generator": "The Instagram QR Code Generator turns your username or profile URL into a scannable code that opens your Instagram profile one tap from Follow. Brand it with your colors or a gradient, choose dot and eye styles, drop in your logo or profile picture, then download print-ready PNG, SVG or PDF. Everything runs in your browser.",
  "javascript-beautifier": "Formatting JavaScript, TypeScript, JSX and TSX with the Prettier engine, the JavaScript Beautifier turns minified or messy code into clean, syntax-aware output. Control semicolons, single versus double quotes, tab width, print width and trailing commas. Free and fully client-side. Nothing is uploaded, and everything runs in your browser.",
  "javascript-minifier": "The JavaScript Minifier compresses scripts using terser, mangling names, eliminating dead code and stripping comments, while optionally keeping class and function names. It shows the exact bytes saved as you go. Free and browser-based, it produces production-grade output locally so your code is never uploaded.",
  "jpg-to-pdf": "GigAI JPG to PDF turns photos into a single PDF in your browser - drag to order pages, then download one file. Our benchmark built a 2-page PDF from 3.4 MB photos in 1.5 seconds. Nothing uploads: phone-photographed paperwork stays on your device. Compress the result if a portal has a size cap.",
  "jpg-to-png": "GigAI JPG to PNG converts photos to lossless PNG in your browser - useful when a system only accepts PNG or when you need an alpha-capable canvas for editing. Honest note: PNG files of photographs are LARGER than JPGs. Convert for compatibility, not size. Nothing uploads, no account.",
  "json-diff": "The JSON Diff compares two JSON documents by structure rather than text, ignoring reordered keys and whitespace. It reports added, removed and changed values by path, color-coded with counts, so a real data change never hides behind formatting. Free and 100% client-side, both documents stay in your browser.",
  "json-formatter": "The JSON Formatter beautifies, validates and minifies JSON instantly, and when input is broken it pinpoints the exact error line and column with a jump-to-error link. It also supports key sorting and live editing. Free and fully in-browser, so your JSON is never uploaded or stored anywhere.",
  "json-to-csv": "JSON to CSV converts a pasted JSON array of objects into a spreadsheet-ready CSV in your browser. It adds a header row, automatically flattens nested keys, and lets you choose a comma, semicolon or tab delimiter. Copy or download the result instantly. Free and fully client-side, with nothing uploaded.",
  "json-to-typescript": "Converting JSON into TypeScript, the JSON to TypeScript tool generates interfaces or types in real time, merging types across every array element for inference naive converters miss. Toggle interface versus type, readonly, export, optional-from-null and naming. Free and client-side, your JSON is turned into types entirely in the browser.",
  "json-tree-viewer": "The JSON Tree Viewer renders JSON as an interactive, collapsible tree with type and array-length badges on every node. Expand or collapse branches, search keys and values with live highlighting and next/prev jumping, and copy any value or its JSONPath in one click. Free and fully in-browser. Nothing is uploaded.",
  "json-validator": "The JSON Validator checks JSON against RFC 8259, pointing at the exact error line and column with a caret under the broken character and a plain-English explanation. One-click auto-fix handles trailing commas and single quotes, plus depth, key-count and type stats. Free and client-side, with nothing uploaded.",
  "jsonld-validator": "The JSON-LD Validator parses a pasted script tag or object, pinpointing syntax errors, then walks every node and @graph to detect each @type and check schema.org's required and recommended properties. Findings return as pass/warn/fail with a 0–100 score and re-formatted output. Free and local, so competitor snippets and drafts stay private.",
  "jwt-decoder": "The JWT Decoder inspects any JSON Web Token, showing color-coded header, payload and signature, with human-readable issued-at and expiry times. It can optionally verify an HS256 signature locally against your secret. Free and 100% in-browser, your token never leaves your device, safe for live or production JWTs.",
  "keyword-density-checker": "The Keyword Density Checker strips tags from pasted text or HTML, then ranks single words and 2- and 3-word phrases by count and density percentage, filtering stopwords. A live meter flags over-optimisation once a term passes roughly 3–4%. Export as CSV or Markdown. Free and browser-based, so unpublished drafts stay private.",
  "linkedin-qr-code-generator": "The LinkedIn QR Code Generator encodes your profile, company page, newsletter or job-post URL into a scannable code people open with one camera tap. Style it in LinkedIn-blue or your own colors, add a logo, then download print-ready PNG, SVG or PDF. Free and built entirely in your browser with nothing uploaded.",
  "local-business-schema-generator": "The LocalBusiness Schema Generator builds valid LocalBusiness JSON-LD with a structured address, geo coordinates, a seven-day OpeningHoursSpecification table, price range and sameAs social profiles. Pick a precise subtype like Restaurant, Store or Dentist, and a validity check grades required fields. Free and browser-based, so your address and hours stay private.",
  "location-qr-code-generator": "The Location QR Code Generator turns GPS latitude and longitude into a geo: QR that drops a pin in Google Maps or Apple Maps with directions one tap away. Add an optional label, style the code and add a logo, then download print-ready PNG, SVG or PDF. Encoded entirely in your browser, nothing uploaded.",
  "m4a-converter": "The M4A Converter turns audio into an Apple-friendly M4A, AAC wrapped in an MP4 container that iPhone, iPad, Mac, iTunes and GarageBand play natively and that often beats MP3 at the same bitrate. Drop WAV, MP3, OGG or FLAC. It decodes to lossless WAV, then transcodes to AAC output. Preview the waveform first. Runs locally, nothing uploaded.",
  "markdown-preview": "The Markdown Preview renders GitHub-Flavoured Markdown as clean, sanitised HTML side-by-side as you type, supporting tables, task lists, code blocks and links. A formatting toolbar inserts the syntax, and you can copy the output as HTML. Free and client-side, everything runs in the browser with nothing uploaded.",
  "markdown-to-pdf": "Markdown to PDF converts written or pasted Markdown into a clean, printable PDF in your browser. A live GitHub-flavoured split-pane preview renders headings, tables, code blocks and task lists, and you control page size, margins and theme. Ideal for READMEs, notes and docs. Free and private. Nothing is uploaded.",
  "menu-qr-code-generator": "The Menu QR Code Generator encodes your online menu link, whether a PDF, Square, Toast, Google Doc or Instagram page, into a table-tent QR wrapped in a 'Scan for Menu' frame so diners open it on their own phone. Brand it, add your logo, then download print-ready PNG, SVG or PDF. Runs entirely in your browser.",
  "merge-pdf": "GigAI Merge PDF combines documents in your browser using pdf-lib page copying - lossless, so text stays sharp and selectable, and the files are never transmitted to any server. Our benchmark merged two 6.6 MB PDFs in 1.0 second. No account, no page limit, no watermark - safe for contracts and anything confidential.",
  "meta-description-generator": "The Meta Description Generator helps write the ~155-character summary Google shows in results, with a dual character-and-pixel meter that flags truncation, a live desktop and mobile SERP preview, and intent-based templates for blog, product and local pages. Copy the finished meta tag. Free and browser-based, so draft copy stays private.",
  "meta-tag-analyzer": "The Meta Tag Analyzer audits a pasted page's head, extracting title, description, canonical, robots, viewport, charset, Open Graph and Twitter Card tags, then scoring each against best practice with a 0–100 grade. Live Google and social previews make truncation and missing images visible. Free and local, so competitor HTML stays private.",
  "meta-tag-generator": "The Meta Tag Generator builds a complete head block, title, description, robots, viewport, charset, canonical plus Open Graph and Twitter Card tags, from one form. Live Google, Facebook, X and LinkedIn previews show how the page renders, with length coaching. Copy the escaped markup. Free and browser-based, so drafts stay private.",
  "meta-tag-validator": "The Meta Tag Validator checks a pasted page's head against an explicit SEO rulebook, grading title and description length, canonical, robots, viewport, charset and Open Graph/Twitter completeness as pass, warn or fail with exact fixes and an A–F grade. Free and browser-based via native DOMParser, so staging pages and unreleased copy stay private.",
  "meta-title-preview": "Meta Title Preview assembles your \"Title | Brand\" string the way Google does and renders it for desktop and mobile, measuring rendered pixel width to flag exactly where truncation lands. Front-load detection nudges keywords ahead of the brand. Copy a ready title tag. Free and browser-based, so unpublished pages stay private.",
  "mkv-to-mp4": "MKV to MP4 turns a Matroska file into a widely playable MP4 using FFmpeg in the browser. Because most MKVs already hold H.264 and AAC, it usually does a fast, lossless remux, copying streams into an MP4 shell with no quality loss, plus a re-encode fallback for odd codecs. Free, nothing uploaded.",
  "mov-to-mp4": "MOV to MP4 re-encodes QuickTime .mov clips from iPhones, Macs and cameras into universally compatible H.264/AAC MP4 with faststart for instant playback. A real FFmpeg transcode in the browser, not a rename, with broad-compatibility yuv420p pixels, an in-page preview and one-click download. Free, and nothing leaves your device.",
  "mp3-converter": "The MP3 Converter turns almost any audio into a universally-playable MP3 at a bitrate you choose from 96 to 320 kbps. WAV and MP3 sources encode natively in-browser with lamejs, while M4A, AAC, OGG and FLAC load an on-demand codec only when needed. Preview the waveform, then download. Free, no account, and your file never leaves the tab.",
  "mp4-to-webm": "MP4 to WebM re-encodes an H.264 MP4 into lean VP9 video with Opus audio inside a WebM container, the royalty-free stack browsers decode natively. A quality dial controls the trade-off, and results are typically smaller than the source. Preview and download in-page, free, running entirely in the browser with nothing uploaded.",
  "nanoid-generator": "The Nano ID Generator mints compact, URL-safe, collision-resistant IDs with a live size slider, alphabet presets or a custom alphabet, and bulk output up to 1,000. A real-time collision-odds estimate updates as you adjust settings. Free and fully in-browser, generation happens locally with nothing uploaded.",
  "news-sitemap-generator": "The News Sitemap Generator builds a Google News-compliant sitemap, wrapping each recent article's publication name, language, title and W3C date in news:news markup with escaped XML. It flags articles older than the 48-hour window, the 1,000-URL cap and timezone-less dates. Free and browser-based, so embargoed stories never leave your machine.",
  "ocr-pdf": "GigAI OCR PDF makes scanned PDFs searchable in your browser: pages render locally, tesseract.js reads the words, and an invisible text layer is placed under the untouched page image - so the scan looks identical but becomes selectable and searchable. Languages are stackable (e.g. English + German). Nothing is uploaded.",
  "ogg-converter": "The OGG Converter encodes audio to OGG Vorbis, the open, royalty-free codec favoured by games, Wikipedia and open-source projects that matches MP3 quality at smaller sizes. Drop WAV, MP3, M4A, AAC or FLAC. A WebAssembly codec transcodes decoded PCM at a Vorbis quality level you pick. Preview the waveform, then download, all locally, with nothing uploaded.",
  "open-graph-generator": "The Open Graph Generator produces escaped og: meta tags, og:title, og:description, og:image with alt, og:url, og:type, og:site_name and locale, so links unfurl richly on Facebook, LinkedIn, Slack and WhatsApp. Live Facebook and LinkedIn card previews and 1.91:1 image guidance catch problems early. Free and browser-based, so drafts stay private.",
  "open-graph-preview": "Open Graph Preview renders faithful Facebook and LinkedIn share cards from pasted HTML or typed og: fields, auditing for a missing og:image, clipped title or description, and a non-absolute og:url. It copies a clean Open Graph block. Free and browser-based, never fetching live URLs, so unpublished and staging pages stay private.",
  "organization-schema-generator": "The Organization Schema Generator builds valid Organization JSON-LD with your name, logo, URL, sameAs social profiles and typed contact points for support, sales or technical lines. This is the markup behind a brand's Knowledge Panel and logo in Search. A validity check grades required fields. Free and browser-based, so internal contacts stay private.",
  "password-generator": "Creating strong passwords and memorable passphrases, the Password Generator uses cryptographic entropy and lets you control length, character sets, look-alike exclusion and guaranteed character classes, with a live strength meter and bulk output. Free and 100% in-browser, every password is generated on your device and never uploaded.",
  "payment-qr-code-generator": "The Payment QR Code Generator creates a scannable pay code for UPI, PayPal.me or Bitcoin, showing only the fields each method needs plus an optional amount. It builds the exact upi://pay, PayPal or wallet payload, which you can style and download as PNG, SVG or PDF. Encoded locally in-browser. No payment is processed here.",
  "pdf-editor": "PDF Editor is a browser-based annotation and page studio: add text boxes, freehand ink, highlights and rectangles, stamp a signature or image, and rotate, delete or reorder pages, then export a flattened PDF via pdf-lib. It marks up above the page rather than rewriting set text. Free, watermark-free, nothing uploaded.",
  "pdf-password-protect": "Protect PDF adds a real open password with AES encryption to a PDF, sealing it locally with @cantoo/pdf-lib so any reader prompts for the password before showing a page. You set and confirm the password in your browser, which is never uploaded or stored. Free, watermark-free, with no server copy.",
  "pdf-qr-code-generator": "The PDF QR Code Generator encodes a link to your hosted PDF, on Drive, Dropbox, OneDrive, S3 or your own site, into a branded code that opens the document on any phone. Style it, add a logo, verify it scans, then export print-ready PNG, SVG or PDF. Built in your browser. Your file is never hosted here.",
  "pdf-to-excel": "PDF to Excel extracts tables from a PDF into an editable spreadsheet, where you can fix cells before exporting a real Excel .xlsx or CSV. PDFs that repeat the same labelled box - voter rolls, directories - can extract one row per record instead of the printed layout. Extraction runs in your browser with nothing uploaded. One optional, clearly-disclosed server OCR step exists for PDFs whose broken fonts damage the extracted text, with 30+ languages auto-detected.",
  "pdf-to-html": "PDF to HTML turns a PDF into clean, semantic HTML you can paste into a page, CMS or email. Using pdf.js, it reads each page's text and rebuilds reading-order paragraphs inside per-page sections. It recovers text structure rather than pixel-perfect layout, runs in your browser, and uploads nothing.",
  "pdf-to-jpg": "PDF to JPG converts every page of a PDF into a JPG or PNG image, rendering each page with pdf.js on a canvas. Pick the format and JPG quality, preview each page, then download images singly or as one ZIP. It runs entirely in your browser, free and watermark-free, with no uploads.",
  "pdf-to-ppt": "PDF to PowerPoint turns a PDF into a real .pptx deck in your browser, one slide per page rendered as a crisp full-bleed image. Choose the resolution and a 16:9 or 4:3 aspect ratio, then open the result in PowerPoint, Keynote or Google Slides. Slides are page images, not editable text. Nothing is uploaded.",
  "pdf-to-txt": "PDF to TXT extracts all the text from a PDF into clean, editable plain text, in reading order, so you can copy it or download a .txt file. It reads every page's text layer directly in your browser, with nothing uploaded. Scanned or image-only PDFs need OCR first. Free to use.",
  "pdf-to-word": "GigAI PDF to Word extracts a PDF's text into an editable document in your browser - the file is never uploaded, which matters for contracts. Honest scope: it recovers TEXT, not complex layouts. Multi-column designs and forms won't reproduce pixel-perfectly. For scanned PDFs, run OCR first.",
  "person-schema-generator": "The Person Schema Generator produces valid Person JSON-LD describing an author, founder or speaker, capturing name, job title, employer via worksFor, bio, image and unlimited sameAs links to LinkedIn, GitHub, Wikipedia or ORCID. Strengthening E-E-A-T author signals, it validates required properties. Free and browser-based, so private emails and bios stay on your device.",
  "phone-qr-code-generator": "The Phone QR Code Generator turns a number into a scan-to-call tel: QR that opens the dialler with your number pre-typed, so customers tap once to ring you. Enter it in full international format and the tool strips spaces and dashes. Brand it, add a logo, then export print-ready PNG, SVG or PDF, all in-browser.",
  "png-to-jpg": "Convert PNG images to lightweight JPGs with PNG to JPG, choosing white, black or a custom hex to fill transparent pixels and a quality slider to balance size against detail. Screenshots and photos often shrink 60-90 percent. The flatten and re-encode happen on the browser canvas, free and privately, with no upload.",
  "png-to-svg": "PNG to SVG traces raster images into scalable vector paths, converting PNG, JPG or WebP into editable SVG. Adjust color count and detail, compare raster and vector side by side, then copy or download the result. It works best on flat logos and icons, runs free in the browser, and uploads nothing.",
  "ppt-to-pdf": "PPT to PDF converts a PowerPoint .pptx into a readable, printable PDF in your browser, one slide per page, with each slide's text and embedded images extracted and laid out. It's an honest best-effort layout rather than a pixel-perfect render. Everything runs on your device and nothing is uploaded.",
  "product-schema-generator": "The Product Schema Generator builds valid Product JSON-LD with a nested Offer (price, currency, availability, condition) and AggregateRating, the structured data Google reads for price and star-rating rich results. It expands enum shorthands and validates every required and recommended property. Free and browser-based, so prices, SKUs and margins never leave your machine.",
  "qr-code-decoder": "The QR Code Decoder reads any QR image and returns its exact raw payload byte-for-byte, plus a parsed breakdown of the URL, Wi-Fi, vCard, UPI or geo scheme inside. Paste, drop or upload a PNG, JPG, WEBP or GIF, or use your webcam, and select and copy the untruncated string. Decoding happens in-browser with nothing uploaded.",
  "qr-code-generator": "GigAI QR Code Generator makes static QR codes - the URL is encoded in the pattern itself, so codes never expire, never track scans and need no subscription. Style colors, dot shapes and a centre logo, then export print-ready PNG, SVG, PDF or EPS. Rendered locally with qr-code-styling. Nothing leaves your browser.",
  "qr-code-reader": "The QR Code Reader decodes a QR from an image you already have, revealing the link, Wi-Fi, contact or text inside. Drag or choose a PNG, JPG, WEBP or GIF, paste a screenshot with Ctrl/Cmd+V, or use your camera, and it reads straight from the raw pixels. Decoding is local in your browser with nothing uploaded.",
  "qr-code-scanner": "The QR Code Scanner decodes any code three ways: a live webcam scanner that reads the instant a code enters frame, image upload with drag-and-drop, and clipboard paste of a screenshot. It reveals the link, Wi-Fi, contact or text inside using the jsQR engine on local canvas pixels, so nothing is uploaded from your browser.",
  "qr-code-with-logo": "The QR Code with Logo tool places a PNG, SVG or JPG mark in the centre of a QR without breaking it, cutting a protect-area behind it and bumping error correction to level H. Tune size, padding, colors and shapes, then export high-res PNG, SVG or PDF. A live scan test confirms it works before printing, all in-browser.",
  "reading-time-calculator": "The Reading Time Calculator estimates how long pasted text takes to read at an adjustable words-per-minute pace, with presets for silent reading, reading aloud, speed reading and narration. It shows live word, sentence, paragraph and character stats, exportable as a badge. Free and browser-based, so unpublished scripts stay private.",
  "recipe-schema-generator": "The Recipe Schema Generator builds valid Recipe JSON-LD for Google's recipe rich result, capturing ingredients, ordered steps as HowToStep, prep/cook times in ISO 8601, yield, cuisine, calories as NutritionInformation and an aggregate rating. An eligibility check grades required fields. Free and browser-based, so unpublished recipes stay on your device.",
  "redaction-checker": "The Redaction Checker verifies a PDF is genuinely redacted, not just covered. It compares the rendered page against the underlying text layer to find words still readable beneath black boxes \u2014 the failure that has leaked court filings and contracts. Runs entirely in your browser, so the document never leaves your device.",
  "regex-tester": "The Regex Tester builds and debugs regular expressions with live match highlighting in your test string. Toggle the g/i/m/s/u/y flags, inspect numbered and named capture groups, preview a find-and-replace, and load ready-made patterns from a library. Free and in-browser, running on the browser's own RegExp engine: nothing is uploaded.",
  "remove-metadata":
    "GigAI Remove Metadata strips EXIF from photos in your browser - GPS position, device model, timestamps and editing history - by re-writing the image without those segments. The photo itself is untouched and never uploaded. Check what a file leaks first with GigAI Verify, then strip it here.",
  "reorder-pdf-pages": "Reorder PDF Pages rearranges a document by dragging page thumbnails (or nudging them with Alt+arrow keys) into a new sequence, then rebuilds the file with pdf-lib in that exact order. Pages are re-copied, not re-rendered, so text and image quality are preserved. Free, watermark-free, and entirely in your browser with no uploads.",
  "review-schema-generator": "The Review Schema Generator produces valid Review JSON-LD with the reviewed item, author, star rating and review body, normalising the rating into a Rating node with bestRating/worstRating bounds. A star preview and inline policy notes flag Google's rules against self-serving reviews. Free and browser-based, so reviewer names and ratings stay private.",
  "rich-results-preview": "Rich Results Preview parses pasted JSON-LD or a full page's HTML, detecting every schema.org @type including nested nodes, then checking required and recommended properties and mapping them to eligible Google features like FAQ accordions, price snippets and breadcrumbs. A 0–100 score summarises it. Free and browser-based, so staging markup stays private.",
  "ringtone-maker": "The Ringtone Maker builds a phone ringtone from any song. Drop an MP3, WAV, M4A or OGG, drag a selection over the waveform to grab the hook within a ~40-second window, add fade-in and fade-out, then preview. Download an MP3 or M4A/AAC ready for your phone. The song is decoded locally, so it stays 100% private and nothing is uploaded.",
  "robots-txt-generator": "The Robots.txt Generator builds a spec-correct robots.txt from user-agent groups with allow/disallow rules, crawl-delay, sitemap and host directives. Live lint warnings catch a site-blocking Disallow: /, and presets cover allow-all, block-site, WordPress and block-AI-crawlers. Free and browser-based, so staging paths and unreleased sections stay private.",
  "robots-txt-validator": "The Robots.txt Validator parses a pasted robots.txt into User-agent groups the way crawlers do, flagging a site-blocking Disallow: /, rules placed before any User-agent, misspelled directives, non-numeric crawl-delays and a relative or missing Sitemap. Free and browser-based, reading only what you paste, so pre-launch drafts never leave your machine.",
  "rotate-pdf": "Rotate PDF turns pages 90°, 180° or 270°, either the whole document at once or individual pages, writing the new orientation into each page with pdf-lib so it sticks in any reader. It changes only the rotation flag, keeping text selectable and images sharp. Free, private and watermark-free, with nothing uploaded.",
  "rtf-viewer": "The RTF Viewer opens and reads .rtf (Rich Text Format) files in your browser. Drop or paste an RTF document to see its formatted text, including bold, italic, underline and paragraphs, then export clean HTML or plain text. Free and fully client-side, with nothing uploaded to a server.",
  "schema-generator": "The Schema Markup Generator is a hub for JSON-LD structured data across twelve schema.org types, Article, FAQPage, Product, Organization, LocalBusiness, Event and more, rendering a tailored form per type and validating required and recommended properties for rich results. Free and browser-based, so product prices and event details stay on your device.",
  "schema-validator": "The Schema Validator extracts every JSON-LD block from pasted markup or a full page's HTML, checking each @type against schema.org's required and recommended properties, including nested nodes like an Offer inside a Product. Errors and warnings return with actionable fixes. Free and browser-based, so unpublished markup never leaves your machine.",
  "security-header-checker": "The Security Header Checker parses pasted HTTP response headers and grades the six defensive headers, HSTS, CSP, X-Frame-Options, X-Content-Type-Options, Referrer-Policy and Permissions-Policy, as pass, warn or fail with copy-ready fixes and an A–F score. Free and browser-based, so it works on staging and login-gated pages a public scanner can't reach.",
  "sitemap-validator": "The Sitemap Validator lints a pasted sitemap.xml or sitemapindex against sitemaps.org and Google's rules, checking well-formed XML, that every url has one loc, the 50,000-URL / 50 MB ceiling, HTTPS locations, and valid changefreq and priority values. Free and browser-based with no crawl, so pre-launch sitemaps stay private.",
  "slug-generator": "The Slug Generator turns any title or list into clean, URL-safe slugs, transliterating accents (café → cafe), expanding symbols to words, and letting you set separator, case, length and strict mode. Batch mode slugifies many lines, deduplicating with numeric suffixes. Free and browser-based, so unpublished titles stay private.",
  "sms-qr-code-generator": "The SMS QR Code Generator encodes a phone number and pre-written text into a code that opens the native Messages app with the recipient and body filled in, ready to send. Enter the number in international format, write the message, style the code and add a logo, then download print-ready PNG, SVG or PDF. Built in your browser.",
  "software-schema-generator": "The SoftwareApplication Schema Generator builds valid JSON-LD for apps, SaaS and web games, with applicationCategory, operatingSystem, a nested Offer (handling a price of 0 for free products) and aggregateRating for price and star snippets. A validity check grades required fields. Free and browser-based, so pricing and ratings stay private.",
  "split-pdf": "Split PDF divides one PDF into several smaller files using pdf-lib in the browser: burst every page into its own file, or type custom ranges like 1-3, 4-8, 9 to carve out sections. Preview pages on a thumbnail grid, then download the results separately or as one ZIP. Free, watermark-free, nothing uploaded.",
  "spotify-qr-code-generator": "The Spotify QR Code Generator turns any track, album, artist, playlist, podcast or episode share link into a scannable code that opens the Spotify app or falls back to the web player. Style it with your cover art or logo, colors and dot shapes, then download print-ready PNG, SVG or PDF. Free, no signup, runs in your browser.",
  "sql-formatter": "The SQL Formatter beautifies or minifies queries with a dialect picker covering PostgreSQL, MySQL, T-SQL, BigQuery, Snowflake and more. Choose upper, lower or preserved keyword case and custom indentation, or collapse to a single line. Free and client-side, your queries are formatted in the browser and never uploaded.",
  "ssl-checker": "The SSL Certificate Checker decodes a pasted PEM/X.509 certificate to compute SHA-1 and SHA-256 fingerprints via Web Crypto, and recovers its SAN DNS names and Common Name candidates. It pairs this with a copy-ready TLS/SSL hardening checklist and openssl commands. Free and browser-based, so private certs never leave your machine.",
  "static-qr-code-generator": "The Static QR Code Generator bakes the destination directly into the modules, with no redirect, account or scan tracking, so the code never expires or breaks. Encode a URL, Wi-Fi, vCard, payment or 24 more, style it to your brand, verify it scans, then export PNG, SVG, PDF or EPS. Fully in-browser, printing exactly what phones read.",
  "svg-animation-generator": "GigAI SVG Animation Generator adds CSS and SMIL animation to vector graphics - draw-on strokes, fades, spins and paths - with live preview and copy-ready output. It runs entirely in your browser, so proprietary artwork never leaves your machine.",
  "svg-background-generator": "The SVG Background Generator builds full-bleed hero and section backgrounds as clean SVG in mesh-gradient, dots, grid, waves or blob styles. Set aspect ratio, brand colors, opacity and density, re-roll from a reproducible seed, then copy the SVG or CSS or download SVG/PNG. Free and fully in-browser.",
  "svg-blob-generator": "The SVG Blob Generator creates smooth, organic blob shapes with sliders for complexity, edge contrast and size. Choose solid or two-stop gradient fills, re-roll a reproducible seed for a fresh silhouette, then copy the SVG or export a transparent PNG. It runs free in your browser with nothing uploaded.",
  "svg-code-formatter": "The SVG Code Formatter turns a minified or messy SVG one-liner into clean, indented markup with one element per line. Pick 2-space, 4-space or tab indentation for diff-friendly, reviewable output. Only whitespace changes, so paths, IDs, gradients and titles stay intact. Free, client-side, and nothing is uploaded.",
  "svg-color-editor": "The SVG Color Editor detects every fill, stroke, gradient stop and inline-style color in an SVG and lists them as clickable swatches you recolor with a picker or hex field. Bulk-replace, swap to currentColor, and watch the live preview update, then export. Free and fully client-side, nothing is uploaded.",
  "svg-compressor": "The SVG Compressor optimizes SVG markup and reports the real transfer size, modelling raw, gzip and estimated Brotli payloads so you know the exact bytes crossing the wire. Tune coordinate precision, watch before/after savings on a checkerboard preview, and copy. Free, fully client-side, with nothing uploaded.",
  "svg-editor": "The SVG Editor renders pasted markup instantly on a transparency-aware canvas as you type, then pretty-prints, optimizes with SVGO or minifies in one click. A live inspector counts every element, color and feature, with undo/redo, copy and download. It runs free entirely in the browser and never uploads.",
  "svg-gradient-generator": "GigAI SVG Gradient Generator builds linear and radial gradients as clean, copy-ready SVG code with live preview - angle, stops and easing under your control, output free of editor cruft. Everything runs in the page. Nothing is uploaded and there's no account.",
  "svg-icon-generator": "The SVG Icon Generator normalizes a batch of mismatched SVGs into one consistent set with a uniform viewBox, size, stroke and currentColor, then exports a <symbol> sprite or each cleaned icon. It can also build simple icons from shape presets. Free, in-browser, and nothing is uploaded.",
  "svg-minifier": "The SVG Minifier aggressively shrinks SVG markup by collapsing whitespace, stripping comments, metadata and editor namespaces, rounding coordinates and squeezing to a single line. Choose Safe, Balanced or Aggressive presets and watch the live before/after size and percentage saved. Free, in-browser, nothing uploaded.",
  "svg-optimizer": "The SVG Optimizer runs real SVGO in your browser to clean files exported from Figma, Illustrator or Sketch, stripping editor metadata, rounding coordinates and dropping hidden layers. A before/after size meter shows exact bytes and percent saved, with a checkerboard preview. Free and never uploaded.",
  "svg-path-editor": "The SVG Path Editor edits an SVG path d-string with a live outline preview overlaying every anchor and bezier control handle. A command-by-command breakdown explains each segment in plain English, and one click normalises between absolute and relative coordinates. Free and fully client-side, nothing uploaded.",
  "svg-path-visualizer": "The SVG Path Visualizer draws a pasted path d attribute with anchor points, bezier control handles and color-marked start/end markers, auto-fitting the canvas. A live report shows total length, bounding box, subpaths and a per-command histogram, with editable redraw. Free, client-side, and nothing is uploaded.",
  "svg-pattern-generator": "The SVG Pattern Generator creates seamless tiling backgrounds from dots, grid, diagonal lines, cross, chevron, triangles and circles. Control tile size, colors and stroke, randomise for inspiration, then copy the repeating SVG or paste-ready CSS. Free with undo/redo and live preview, all in your browser.",
  "svg-placeholder-generator": "The SVG Placeholder Generator makes lightweight prototype placeholder images from a set width, height and custom label plus background and foreground colors. Copy the razor-sharp scalable SVG, grab a ready data URI, or download SVG or PNG. Free, with presets and live preview, generated in your browser.",
  "svg-prettifier": "The SVG Prettifier beautifies minified or single-line SVG source into clean, indented markup with one node per line and a tab or space width you choose. A live preview confirms the artwork is untouched since only formatting changes. Free, works offline, and runs entirely in the browser with nothing uploaded.",
  "svg-shape-generator": "The SVG Shape Generator draws crisp geometric shapes including polygons, stars, gears, hearts, sunbursts, hexagons and badges. Adjust sides or points, radius, inner radius and rotation, and choose solid or gradient fill. Copy the pure-math SVG or export a transparent PNG, free and entirely in your browser.",
  "svg-size-optimizer": "The SVG Size Optimizer shrinks an SVG toward a target size by rounding path coordinates decimal-by-decimal with one precision slider. A live meter tracks bytes, gzip estimate and savings percentage while a checkerboard preview proves the curves never move. Free and fully in-browser, nothing is uploaded.",
  "svg-sprite-generator": "The SVG Sprite Generator combines multiple SVG icons into a single <symbol> sprite sheet, naming each and generating a copy-paste <use> snippet. The result is one cached request with icons that inherit currentColor, no build step required. Free and generated entirely in your browser with nothing uploaded.",
  "svg-to-css": "SVG to CSS converts a pasted SVG into a CSS background-image or mask rule, producing a compact URL-encoded data URI with a ready selector snippet. Masks can be recolored with a single background-color. It offers a live preview and one-click copy, runs free in-browser, and uploads nothing.",
  "svg-to-data-uri": "SVG to Data URI converts a pasted SVG into a ready data: URI, either URL-encoded for the smallest CSS payload or base64 for maximum compatibility. Copy it as a background-image, inline img src, or the bare URI, with a live size comparison. Free, one-click, and fully in your browser.",
  "svg-to-html": "SVG to HTML converts a pasted SVG into ready-to-paste page markup, either a clean inline <svg> block that inherits color and scales with CSS, or a self-contained <img> with a data-URI src. It includes a live preview, copy and download. Free, in-browser, and nothing is uploaded.",
  "svg-to-png": "SVG to PNG rasterizes a pasted or dropped SVG into a sharp PNG at any resolution, with 1×–8× scale presets or exact pixel dimensions. Keep transparency or set a background color, preview live, and download in one click. Free and running entirely in the browser, nothing uploaded.",
  "svg-to-react": "SVG to React converts a pasted SVG into a clean, production-ready React component with camelCased attributes and props spread through. Choose TypeScript or JS output and optionally add memo, forwardRef or React Native. A live preview and one-click copy are included, free and fully in-browser.",
  "svg-to-vue": "SVG to Vue converts a pasted SVG into a clean Vue 3 Single-File Component with a <script setup> block, native attributes preserved and caller attributes forwarded through $attrs. Output as TypeScript or JavaScript, with a live preview and one-click copy. Free and running entirely in your browser.",
  "svg-validator": "The SVG Validator checks a pasted SVG for well-formed XML, xmlns and viewBox declarations and sane dimensions, then flags <script>, on* handlers, <foreignObject> and javascript: XSS vectors. A pass/fail checklist sits beside a live preview and composition report. Free, in-browser, never uploaded.",
  "svg-viewer": "GigAI SVG Viewer renders SVG files safely in your browser with zoom, pan, background toggles and source inspection - no upload, which matters because SVGs can contain scripts and you shouldn't paste unknown ones into production. Pair with the SVG Optimizer before shipping.",
  "svg-wave-generator": "The SVG Wave Generator builds layered wave dividers for section transitions, with sliders for height, amplitude, wave count and layers. Set per-layer colors or a gradient, flip top or bottom, and copy the SVG or download SVG/PNG. Free, seed-reproducible, and generated entirely in your browser.",
  "telegram-qr-code-generator": "The Telegram QR Code Generator turns a @username, channel, group invite or bot deep-link into a scannable t.me code that opens Telegram at that spot. Enter a username with or without @, or paste a full t.me, joinchat or bot link, then style it and add a logo. Download PNG, SVG or PDF, all built in your browser.",
  "twitter-card-generator": "The Twitter Card Generator builds escaped twitter:* meta tags for X, letting you pick summary or summary_large_image and set the title, description, image, alt text and @site/@creator handles. A live card preview shows how the link unfurls. Free and browser-based, complementing your og: tags, so drafts stay on your device.",
  "twitter-preview": "Twitter (X) Card Preview renders a pixel-faithful summary or large-image card from typed twitter: fields or pasted HTML, falling back to og: tags as X does. A live audit flags a missing image, clipped title or non-HTTPS URL that collapses a card. Free and browser-based, so unpublished pages stay private.",
  "txt-to-pdf": "Text to PDF converts pasted text or a dropped .txt file into a clean, print-ready PDF with real selectable, searchable text. Pick the font, size, margins and page size (A4 or US Letter), preview the pages, and download. Free and fully in your browser, with nothing uploaded.",
  "unix-timestamp-converter": "The Unix Timestamp Converter turns epoch values into human dates and back, auto-detecting seconds versus milliseconds and showing ISO 8601, UTC, local and relative time. A live-ticking epoch clock runs in seconds and milliseconds, and every field copies in one click. Free and fully in-browser, with nothing uploaded.",
  "unlock-pdf": "Unlock PDF removes the open password from a PDF you own by decrypting it with @cantoo/pdf-lib in your browser using the password you supply, then saving a clean unencrypted copy with selectable text and working links intact. It needs the real password and can't crack unknown ones. Free, private, no uploads.",
  "upi-qr-code-generator": "The UPI QR Code Generator turns your UPI ID, name and optional amount into a Scan & Pay code that opens the payment screen in Google Pay, PhonePe, Paytm, BHIM and every UPI bank app. Enter your VPA like yourname@okhdfcbank, brand it, add a logo, then download print-ready PNG, SVG or PDF. Encoded entirely in your browser.",
  "url-decoder": "The URL Decoder turns percent-encoded text back into plain, readable characters, and when you paste a full link it breaks it into protocol, host, port, path, decoded query parameters and hash. Free and 100% in-browser, the decoding happens in your tab and nothing is uploaded.",
  "url-encoder": "The URL Encoder percent-encodes text and links as you type, with a component mode for query-string values and a full-URL mode that keeps:/?#& structure intact. Encode a whole list line-by-line and copy the result in a click. Unicode-safe, free and 100% in-browser. Nothing is ever uploaded.",
  "url-parser": "GigAI URL Parser breaks any URL into scheme, host, path, query parameters and fragment, decodes every percent-encoded value, and lets you edit parameters and rebuild the URL - all in your browser. Paste a 500-character tracking link and see exactly what's in it. Nothing is sent anywhere.",
  "utm-builder": "The UTM Builder assembles a GA4-ready campaign URL from a form, setting utm_source, utm_medium and utm_campaign plus optional utm_term and utm_content, preserving existing parameters and percent-encoding values. Optional lowercasing prevents fragmented sources, with presets for common channels. Free and browser-based, so campaign names and draft URLs stay private.",
  "uuid-generator": "The UUID Generator produces cryptographically secure, RFC 9562-compliant identifiers, random v4, time-ordered v7, or the nil UUID. Generate one or up to 1,000 at once and copy or export as TXT or CSV. Free and fully in-browser, every UUID is created locally with nothing uploaded.",
  "vcard-qr-code-generator": "The vCard QR Code Generator assembles your name, title, company, phones, email, website and address into a standard vCard 3.0 code that saves to a phone's contacts in one scan. Brand it with colors and a logo, then download print-ready PNG, SVG or PDF for cards and badges. Everything is built in your browser, nothing uploaded.",
  "video-compressor": "The Video Compressor shrinks MP4, MOV, WebM, MKV, AVI and M4V files using FFmpeg (libx264/AAC) in the browser. A plain-English quality slider drives the encode, and an exact before/after meter shows the bytes and percentage saved next to a live preview. Output is a universally playable MP4. Free, nothing uploaded.",
  "video-converter": "The Video Converter transcodes between MP4, WebM, MOV, AVI, MKV and GIF using FFmpeg in the browser, picking the correct codec pipeline for whichever target you choose. It offers MP4 quality control, web-ready faststart output, plus an in-page preview and download. Free to use, with every file processed privately and nothing uploaded.",
  "video-crop": "The Video Cropper reframes MP4, MOV, WebM, MKV and AVI footage by dragging a crop box over a live preview or snapping to a 1:1, 9:16, 4:5 or 16:9 preset. A real-pixel readout, size delta and one-click download follow. Free, with no watermark, no account and nothing uploaded.",
  "video-frame-extractor": "GigAI Video Frame Extractor captures exact frames from a video as PNG or JPG in your browser - step to the moment, grab the frame at source resolution, nothing uploaded. Our thumbnail workflow pairs it with the Image Compressor for web-ready stills.",
  "video-intelligence": "GigAI Video Intelligence transcribes video and audio entirely on your own device, running OpenAI's Whisper model in the browser via transformers.js - the recording is never uploaded anywhere. It produces an editable transcript with speaker labels, keywords and caption export (SRT/VTT). Free, no account, and it keeps working offline after the one-time model download.",
  "video-loop": "The Video Looper repeats a clip a set number of times, stitching 2, 5, 10 or more copies end-to-end into one longer continuous file. It handles MP4, MOV, WebM, MKV and AVI, outputting MP4, WebM or MKV. Free and running entirely in the browser with no uploads, account or watermark.",
  "video-merger": "The Video Merger combines multiple clips into a single MP4. Add your videos, drag rows to reorder or remove them, and merge. Mismatched sizes and formats are re-encoded to a common baseline automatically. Accepts MP4, MOV, WebM, MKV and AVI. Free, running in the browser with no uploads, account or watermark.",
  "video-metadata": "GigAI Video Metadata reads a video file's real properties in your browser - container, codecs, resolution, frame rate, bitrate, duration and embedded tags - by parsing the file locally. Nothing uploads. Use it to learn why a platform rejects an upload before transcoding blindly.",
  "video-mute": "The Video Muter strips the audio track entirely out of an MP4, MOV, WebM, MKV or AVI, leaving a genuinely silent file with no residual soundtrack while the picture stays untouched. Preview the result and download as MP4, MOV, WebM or MKV. Free, running in the browser with no uploads or watermark.",
  "video-player": "GigAI Video Player plays local video files (MP4, WebM, MOV and more) right in your browser with frame stepping, speed control, looping and bookmarks - no installation and no upload, so it also works on locked-down machines. If the file won't play, the Video Converter re-encodes it to a compatible format.",
  "video-qr-code-generator": "The Video QR Code Generator encodes a link to your hosted or streamed video, an MP4/WEBM on your CDN, Vimeo, Wistia, Loom or a Drive share, into a branded scan-to-watch code. Add colors and a logo, run a live scan check, then export print-ready PNG, SVG or PDF. Built in-browser. The video isn't hosted here.",
  "video-resizer": "GigAI Video Resizer changes a video's frame size in your browser using ffmpeg compiled to WebAssembly, re-encoding to H.264 - nothing installs and nothing uploads. It's the right tool when a platform wants 1080\u00d71920 or a form wants 720p. For file-SIZE reduction at the same dimensions, the Video Compressor does that.",
  "video-reverse": "The Video Reverser rewrites frames in reverse order so an MP4, MOV, WebM, MKV or AVI plays backwards along with its audio, producing a real reversed file rather than a playback trick. Preview the result and download as MP4, WebM or MKV. Free, running in the browser with no uploads or watermark.",
  "video-rotate": "The Video Rotator turns a sideways or upside-down clip 90°, 180° or 270° and bakes the rotation into the file, correctly swapping dimensions on the quarter-turns so a portrait clip ends up upright. Works on MP4, MOV, WebM, MKV and AVI. Free, in the browser, with no uploads, account or watermark.",
  "video-schema-generator": "The Video Schema Generator builds valid VideoObject JSON-LD for Google's video carousel and thumbnails, capturing name, thumbnailUrl, uploadDate, description and content/embed URLs. Enter runtime in minutes and seconds and it converts to ISO-8601 duration. A YouTube helper derives URLs. Free and browser-based, so video URLs and descriptions stay private.",
  "video-sitemap-generator": "The Video Sitemap Generator wraps each watch page in a video:video block carrying thumbnail, title, description, player or content URL, duration and publish date, with the correct namespace and escaped XML. It validates required fields and the 1–28,800-second duration range. Free and browser-based with no crawl, so members-only video URLs stay private.",
  "video-speed": "The Video Speed Changer sets any playback speed from a 0.25× slow-motion crawl to a 4× fast-forward, with presets and a live readout of the new duration. Keep the audio pitch natural or drop the sound. Handles MP4, MOV, WebM, MKV and AVI. Free, in the browser, no uploads or watermark.",
  "video-splitter": "The Video Splitter cuts one video into multiple clips, either equal-length chunks every N seconds or your own custom start-end timecode ranges. Download each part individually or grab them all as a ZIP. Accepts MP4, MOV, WebM, MKV and AVI. Free, running in the browser with no uploads, account or watermark.",
  "video-thumbnail-generator": "The Video Thumbnail Generator captures a still frame from an MP4, MOV, WEBM, MKV or M4V at the exact second you scrub to, saving it as a lossless PNG or a quality-adjustable JPG. It uses the browser's decoder, so there's no FFmpeg engine to wait on. Free, instant, and nothing is uploaded.",
  "video-to-gif": "Video to GIF converts MP4, WebM, MOV or MKV clips into clean, loopable animated GIFs using a two-pass palette (palettegen and paletteuse) for faithful color. Adjust the start, duration, frame rate and width, then preview and download. Free, running entirely in the browser with nothing uploaded.",
  "video-to-work":
    "GigAI Video \u2192 Work turns a client screen recording into developer tasks: transcription and frame selection happen on your device, then the transcript text (never the video) goes to the analysis step with explicit disclosure - or entirely locally via Ollama. Findings carry the client's words, a timestamp and the screenshot they happened on.",
  "video-trimmer": "The Video Trimmer cuts a clip by dragging two handles across a filmstrip of real frames to set in and out points to a tenth of a second, dimming the area outside your selection. Preview then download as MP4, WebM or MKV. Accepts MP4, MOV, WebM, MKV and AVI. Free, nothing uploaded.",
  "video-watermark": "The Video Watermarker overlays a text caption (name, handle, URL or copyright line) or a logo image onto an MP4, MOV, WebM, MKV or AVI. Position it in any corner or the centre, set opacity, and control text font, size and color. Free, in the browser, with no uploads and no second watermark.",
  "wav-converter": "The WAV Converter produces an uncompressed PCM WAV that every DAW, sampler, editor and game engine reads without a codec. Drop MP3, M4A, AAC, OGG or FLAC and choose the sample rate (44.1/48 kHz and up), 16- or 24-bit depth and mono/stereo. Preview the waveform, then download. Re-encoded natively in the tab, so nothing is uploaded.",
  "webm-to-mp4": "WebM to MP4 re-encodes VP8 or VP9 WebM files into universally compatible H.264/AAC MP4, the most broadly supported video codec, hardware-decoded on nearly every phone, laptop, TV, console and editor. Preview the result in-page and download. Free, running entirely in the browser with nothing uploaded and no watermark.",
  "webp-converter": "The WebP Converter works both directions: encode PNG or JPG to a lean WebP with a quality dial for smaller, faster-loading files, or decode a .webp back to PNG or JPG for wider compatibility. Transparency survives the round trip. Conversion runs on the browser canvas, free and private, with no upload.",
  "whatsapp-qr-code-generator": "The WhatsApp QR Code Generator turns your number and an optional pre-written message into a code that opens a WhatsApp chat already addressed to you, ready to send. Enter the number in full international format, brand the code and add a logo, then download print-ready PNG, SVG or PDF. Everything runs in your browser, nothing uploaded.",
  "wifi-qr-code-generator": "The WiFi QR Code Generator builds a standard WIFI: code so guests join your network with one tap and no typed password. Enter the SSID, choose WPA/WPA2/WPA3, WEP or open, add the password and flag a hidden network. Style it, add a logo, then download print-ready PNG, SVG or PDF, all built in your browser.",
  "word-counter": "The Word Counter is a live writing dashboard reporting words, characters with and without spaces, sentences, paragraphs, lines and UTF-8 bytes, plus estimated reading and speaking time and a ranked keyword breakdown. Length gauges check tweet, SEO title, meta and SMS limits. Free and browser-based, so drafts stay private.",
  "word-to-pdf": "GigAI Word to PDF converts a .docx into a PDF in your browser using mammoth and jsPDF - no Office install, no upload. Honest scope: output is rendered (text not selectable) and complex layouts are approximated. It's built for getting a clean, portal-acceptable PDF out of a normal document.",
  "xml-formatter": "The XML Formatter beautifies or minifies XML with real well-formedness checking, preserving CDATA, comments, the declaration and processing instructions untouched. When markup is broken, it points at the precise error line. Free and client-side, your XML is processed in the browser and never uploaded.",
  "xml-sitemap-generator": "The XML Sitemap Generator turns a pasted list of URLs into a spec-valid sitemap.xml with per-URL changefreq, priority and lastmod, escaping XML characters automatically. Live validation flags non-HTTPS locations, out-of-range priorities, duplicates and the 50,000-URL limit. Free and browser-based with no crawl, so staging URLs never leave your machine.",
  "yaml-formatter": "The YAML Formatter re-indents, cleans and validates YAML, or converts YAML to JSON and back, with key sorting and flow or block style. When input won't parse, it reports the exact error line and column. Free and 100% client-side, your YAML stays in the browser with nothing uploaded.",
  "youtube-qr-code-generator": "The YouTube QR Code Generator turns any channel, video, Short, playlist or @handle link into a branded scannable code, normalising the URL and stripping tracking while keeping the video ID and timestamp. Style it in YouTube-red or your colors, add a logo, run a scan check, then download print-ready PNG, SVG or PDF. Nothing uploaded.",
  "zoom-qr-code-generator": "The Zoom QR Code Generator encodes a meeting join link, including an embedded passcode, into a scannable code that launches the Zoom app or browser straight into the join flow, so attendees skip typing Meeting IDs. Brand it, add a logo, then download print-ready PNG, SVG or PDF. Built entirely in your browser with nothing uploaded.",

  // ── GEO Studio ──────────────────────────────────────────────────────────────
  "geo-audit": "The GigAI GEO Audit takes one URL and reports whether AI systems can find, read and cite that page. It checks 15 AI crawler tokens against robots.txt with real RFC 9309 matching, detects Cloudflare's default AI blocking, counts the words visible without JavaScript, scores citability using the KDD 2024 GEO study's factors, and slices the page into retrieval chunks. Every finding links to the free tool that fixes it.",
  "ai-crawler-access-checker": "The AI Crawler Access Checker reports whether GPTBot, ClaudeBot, OAI-SearchBot, PerplexityBot, Bingbot and 10 more AI crawler tokens may fetch your site, computed with real RFC 9309 matching: user-agent group specificity, wildcard paths, longest-match precedence and Allow beating Disallow on ties. Each verdict quotes the exact robots.txt line that decided it. It also detects Cloudflare, which blocks AI crawlers by default on new zones regardless of robots.txt.",
  "ai-robots-txt-generator": "The AI Robots.txt Generator builds a correct robots.txt policy for 15 AI crawler tokens with one toggle each, grouped by operator and labeled by role: model training, AI search indexing, or on-demand user fetching. Blocking a bot immediately shows what it costs, and three presets cover the sane policies. Output is a merge-ready block or a complete file, generated entirely in your browser.",
  "ai-crawler-log-analyzer": "The AI Crawler Log Analyzer parses nginx and Apache access logs in your browser to show which AI crawlers actually visited: per-bot request counts, first and last seen, most-fetched paths, HTTP status health and a daily trend. It also lists pages no AI crawler has ever fetched. Access logs contain visitor IP addresses, so nothing is uploaded and the IP column is discarded at parse time.",
  "js-rendering-checker": "The JS Rendering Checker shows your page as AI crawlers see it: without JavaScript. It fetches the raw HTML, counts the words that survive, detects client-rendering framework markers with the evidence quoted, and estimates prose trapped in serialized JS data. Paste the rendered DOM alongside and it diffs the two, reporting exactly what percentage of the page is invisible to GPTBot, ClaudeBot and PerplexityBot.",
  "content-citability-scorer": "The Content Citability Scorer rates content on six factors: fact density, source citations and quotability (measured by the Aggarwal et al. GEO study at KDD 2024), plus answer-first openings, question headings and self-containment. Every sub-score prints its formula, its counted inputs and the evidence it counted, so the arithmetic is checkable rather than a black-box number. Runs entirely in your browser.",
  "retrieval-chunk-preview": "The Retrieval Chunk Preview splits a page the way a RAG system does, by heading section then ~300-token windows with overlap, and shows every chunk in isolation exactly as a model receives it. It flags fragments that collapse alone: pronoun openers with no antecedent, 'as mentioned above' back-references, chunks that never name their subject, and link-list boilerplate. The verdict is one number: how many of your chunks fail.",
  "answer-snippet-checker": "The Answer Snippet Checker takes every H2 section of your page and judges its opening against one standard: a self-contained answer in 40 words or fewer, with no throat-clearing and no dependence on surrounding text. Each failure shows the actual opening, the specific reasons it failed and a rewrite target tied to that heading. Works on Markdown, HTML or a fetched URL, entirely in your browser.",
  "entity-consistency-checker": "The Entity Consistency Checker compares your brand description across your website, GitHub, LinkedIn, Product Hunt, Crunchbase and other listings, flagging the contradictions that stop models corroborating facts about you: name-spelling variants, numbers that conflict when paired with the same unit, conflicting years, and profiles too thin to support the others. Nothing is fetched or uploaded. It reads only what you paste.",
  "llms-txt-generator": "The llms.txt Generator builds a spec-shaped llms.txt from your sitemap.xml or URL list, grouping pages into readable sections with humanized titles and a summary blockquote. It also states the thing most llms.txt tools omit: Google has said its AI search does not use llms.txt, and no major AI operator documents it as a ranking input. Useful for agents that do fetch it, not a ranking lever.",
  "ai-schema-checker": "The AI Schema Checker audits a page's JSON-LD against the seven schema types AI retrieval leans on (Organization, WebSite, FAQPage, HowTo, SoftwareApplication, Article, BreadcrumbList), verifies each type carries its load-bearing properties, and counts blocks that fail to parse entirely. It separates site-identity gaps from content types you shouldn't add, and links each gap to the existing GigAI generator that fills it.",
};

/** Bespoke AI answer for a tool, or undefined if none is written yet. */
export function getToolAnswer(slug: string): string | undefined {
  return TOOL_ANSWERS[slug];
}
